#!/usr/bin/env python3
"""arrays-mutated-near-allocation.py <part 0..7>: THE WHOLE TABLE, not a sample: an array MADE IN THE FUNCTION, altered IN THE FUNCTION (every alteration of altered-arrays.py), then the built-in that the alteration is about (for an own property under a method's name: that method; for the others: fourteen uses), in four forms: in a row; the alteration behind a call that is handed the array; behind an alias; in the second turn of a loop round the use. As plain Bun or a throw."""
import sys, importlib.util, io, contextlib
part = int(sys.argv[1]) if len(sys.argv) > 1 else 0
spec = importlib.util.spec_from_file_location('g', __file__.replace('arrays-mutated-near-allocation.py', 'altered-arrays.py'))
g = importlib.util.module_from_spec(spec); argv = sys.argv; sys.argv = ['gen.py', '1', 'ts']
with contextlib.redirect_stdout(io.StringIO()): spec.loader.exec_module(g)
sys.argv = argv
A = ': any'
GENERAL = ['a.push(9)', 'a.pop()', 'a.map((x: any) => x)', 'a.slice(1)', 'a.concat([9])', 'a.join("-")', 'a.indexOf(2)', '[...a]', 'a.filter(() => true)', 'a.splice(0, 1)', 'String(a)', 'JSON.stringify(a)', 'a.length', '(() => { const r = []; for (const x of a) r.push(x); return r; })()', 'a.includes(2)', 'a.reverse()', 'a.flat()', 'a.at(0)', 'a.shift()', 'a.unshift(0)', 'a.fill(0)', 'a.sort()', 'a.forEach(() => {})', 'Array.from(a)', 'a.toString()']
rows = []
for name, text in g.ALTER:
    m = name.split(' ')[1] if name.startswith('own ') else None
    uses = [u for u in g.USES if m and ('a.%s(' % m) in u][:2] if m in g.METHODS else GENERAL
    if m in ('join', 'toString'): uses = uses + ['String(a)', 'a + ""']
    for u in uses: rows.append((name, text, u))
MAKERS = ['[1, 2, 3]', '[0.5, 1.5]', '["a", "b", "c"]', '[recs[0], recs[1]]', '[]', 'new Array(3)', '[3, 1, 2].map(x => x)', '[5, 6, 7].slice(1)', 'rest(1, 2)', 'Array.of(4, 5)', '[...[8, 9]]', '[5, 6].concat([7])', 'Array.from([1, 2])', '"x,y".split(",")', 'Object.keys({ k: 1 })', '[1, 2, 3].filter(() => true)']
head = [l for l in g.out if l.startswith(('declare', 'const show', 'const recs', 'class Mine', 'class Plain', 'function rest', 'const attempt'))]
out = ['// generated by arrays-mutated-near-allocation.py %d' % part] + head + ['function hidden(a: any, f: (a: any) => void) { f(a); }', 'const said: string[] = [];']
names = []
n = 0
for i, (name, text, use) in enumerate(rows):
    for form in range(4):
        n += 1
        if n % 8 != part: continue
        m = MAKERS[(i + form) % len(MAKERS)]
        body = ['const a%s = %s; %s return %s;' % (A, m, text, use), 'const a%s = %s; hidden(a, (a%s) => { %s }); return %s;' % (A, m, A, text, use), 'const a%s = %s; const b = a; { const a = b; %s } return %s;' % (A, m, text, use), 'const a%s = %s; for (let i = 0; i < 2; i++) { if (i) { %s } said.push(attempt(() => %s)); } return said.splice(0).join(" then ");' % (A, m, text, use)][form]
        out.append('function g%d() { %s }' % (n, body)); names.append((n, '%s | %s | %s | form %d' % (name, use.replace('"', "'"), m.replace('"', "'"), form)))
out.append('const ALL: [string, () => unknown][] = [%s];' % ', '.join('["%s", g%d]' % (t.replace('\\', ''), k) for k, t in names))
out.append('for (let turn = 0; turn < 3; turn++) for (const [name, f] of ALL) { const r = attempt(f); if (turn !== 1) console.log(turn + " " + name + ": " + r); }')
print('\n'.join(out))
